// Las cifras vienen de SQL; la IA solo las interpreta. El periodo lo fija config_reporte (acumulado o últimas N h).
const m = $('Leer métricas 24 h').first().json;
const p = $('Leer prompt P4').first().json;
const periodo = ($('Leer métricas 24 h').first().json.periodo) || null;
return [{ json: { metricas: m, body: { model: 'gpt-4o-mini', temperature: 0.2, messages: [ { role: 'system', content: p.texto + '\n\nIMPORTANTE: las métricas que recibes cubren el periodo indicado en el campo "periodo" del JSON. No digas "últimas 24 horas" salvo que ese sea el periodo.' }, { role: 'user', content: JSON.stringify(m) } ] } } }];

// Reporte ejecutivo en capas. Todo lo calcula SQL (v_reporte_lider y v_tablero_b); P4 solo aporta la línea de prioridad.
// La foto es la captura del tablero web (flujo F); si la captura falla, se usa la dona de gestión.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const arr = (v) => Array.isArray(v) ? v : (typeof v === 'string' ? JSON.parse(v || '[]') : []);
const obj = (v) => (v && typeof v === 'object') ? v : (typeof v === 'string' ? JSON.parse(v || '{}') : {});
const WEB = 'https://TU_INSTANCIA.app.n8n.cloud/webhook/tablero-soporte?k=TU_LLAVE_TABLERO';
const bajoDemanda = $('Actualizar desde Telegram').isExecuted;
const r = $('Leer reporte ejecutivo').first().json || {};
const k = obj(r.kpis);
const b = $('Leer tablero B').first().json || {};
const kb = obj(b.kpis);
const periodo = b.periodo || k.periodo || 'últimas 24 h';
const cap = (($('Captura del tablero').first().json || {}).data || {}).screenshot || {};
const foto = cap.url || $('Armar gráficas').first().json.urls[0];
const dec = arr(r.decisiones);
const sem = { rojo: '🔴', amarillo: '🟡', verde: '🟢' }[r.semaforo] || '⚪';
const dur = (m) => { m = Math.abs(Number(m)); return m >= 60 ? Math.round(m / 60) + ' h' : m + ' min'; };
const plazo = (m) => (m === null || m === undefined) ? 'por confirmar' : (Number(m) < 0 ? 'vencido hace ' + dur(m) : 'vence en ' + dur(m));
const motivo = (r.motivo || 'Sin pendientes urgentes').replace('SLA en riesgo', 'SLA vencidos o en riesgo');
const p4 = (($('P4 · Resumen del líder').first().json.choices || [])[0] || {}).message?.content || '';
const mp = p4.match(/Prioridad de hoy:\s*([^\n]+)/i);
const prioridad = mp ? mp[1].trim() : '';
const fecha = $now.setZone('America/Bogota').toFormat('dd/MM HH:mm');
const decis = dec.slice(0, 5).map(d => ({ etiqueta: d.etiqueta, numero_caso: d.numero_caso, severidad: d.severidad, pais: d.pais, cliente: d.cliente, tipo: d.tipo, plazo: plazo(d.min_restantes) }));
const lineas = decis.slice(0, 3).map((d, i) => (i + 1) + '. ' + esc(d.etiqueta) + ' #' + d.numero_caso + ' · ' + esc(d.severidad) + ' ' + esc(d.pais) + ' · ' + esc(d.plazo));
const mas = dec.length > 3 ? '\n…y ' + (dec.length - 3) + ' más en <b>Pendientes</b>' : '';
const nRes = k.resueltos_24h ?? 0, nIng = k.en_ingenieria ?? 0;
let msg = sem + ' <b>' + (bajoDemanda ? 'Reporte actualizado' : 'Soporte') + ' · ' + fecha + '</b>\n' + esc(motivo) + '\n<i>Cifras: ' + esc(periodo) + '</i>\n\n' +
  '📂 ' + (kb.abiertos ?? 0) + ' abiertos · ✅ ' + (kb.cerrados ?? 0) + ' cerrados\n' +
  '⏱ SLA 1ª respuesta ' + (kb.sla_respuesta_pct ?? 0) + ' % (' + (kb.respondidos_a_tiempo ?? 0) + ' de ' + (kb.respondidos ?? 0) + ' a tiempo)\n' +
  '⏰ ' + (kb.vencidos ?? 0) + ' vencidos (' + (kb.pct_vencidos ?? 0) + ' %): ' + (kb.vencidos_abiertos ?? 0) + ' siguen abiertos\n' +
  '✍️ ' + (k.por_aprobar ?? 0) + ' por aprobar · 🛠 ' + (k.escalamientos_abiertos ?? 0) + ' por escalar · 🚨 ' + (k.incidentes_abiertos ?? 0) + ' incidentes' +
  (lineas.length ? '\n\n<b>Necesita tu decisión</b>\n' + lineas.join('\n') + mas : '\n\n✅ Nada pendiente de tu decisión.');
const pie = '\n\n👇 Toca un botón para ver el detalle o abre el tablero web';
const lineaPrio = prioridad ? '\n\n<b>Prioridad de hoy:</b> ' + esc(prioridad.length > 220 ? prioridad.slice(0, 220) + '…' : prioridad) : '';
if ((msg + lineaPrio + pie).replace(/<[^>]+>/g, '').length <= 1000) msg += lineaPrio;
msg += pie;
return [{ json: {
  mensaje: msg, foto, foto_es_tablero: !!cap.url, web: WEB,
  n_sla: k.sla_en_riesgo ?? 0, n_inc: k.incidentes_abiertos ?? 0, n_pen: dec.length, n_res: nRes, n_ing: nIng,
  semaforo: r.semaforo || 'verde', motivo, periodo, kpis: k, tablero: b, decisiones: decis, prioridad, p4, bajo_demanda: bajoDemanda
} }];

// Correo ejecutivo: semáforo, tablero B (matriz severidad × SLA con abiertos y cerrados), decisiones, gráficas y lectura del día.
// Cada celda, total y caso del tablero abre el detalle en la web (flujo F); los botones de decisión abren el bot de Telegram.
// Paleta pública de Truora, sin logo. Cifras desde SQL (v_tablero_b, v_reporte_lider). El periodo lo fija config_reporte.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const arr = (v) => Array.isArray(v) ? v : (typeof v === 'string' ? JSON.parse(v || '[]') : []);
const obj = (v) => (v && typeof v === 'object') ? v : (typeof v === 'string' ? JSON.parse(v || '{}') : {});
const dest = Object.fromEntries($('Leer destinatarios').all().map(i => [i.json.rol, i.json.correo]));
const c = $('Componer resumen').first().json;
const gr = $('Armar gráficas').first().json;
const BOT = 'https://t.me/TU_BOT?start=';
const WEB = c.web;
const w = (p) => (WEB + Object.entries(p || {}).map(([a, b]) => '&' + a + '=' + encodeURIComponent(b)).join('')).replace(/&/g, '&amp;');
const fecha = $now.setZone('America/Bogota').setLocale('es').toFormat("cccc d 'de' LLLL");
const hora = $now.setZone('America/Bogota').toFormat('HH:mm');
const S = { rojo: ['#D92D20', '#FEE4E2', 'Rojo'], amarillo: ['#B54708', '#FEF0C7', 'Amarillo'], verde: ['#067647', '#DCFAE6', 'Verde'] }[c.semaforo] || ['#475569', '#F1F5F9', ''];
const b = c.tablero || {};
const kb = obj(b.kpis), tot = obj(b.totales), mx = arr(b.matriz), pa = arr(b.por_atender), pe = arr(b.pendientes);
const periodo = c.periodo || 'últimas 24 h';
const dur = (m) => { m = Math.abs(Math.round(Number(m) || 0)); if (m < 60) return m + ' min'; if (m < 1440) { const h = Math.floor(m / 60), r = m % 60; return h + ' h' + (r ? ' ' + r + ' min' : ''); } const d = Math.floor(m / 1440), h = Math.round((m % 1440) / 60); return d + ' d' + (h ? ' ' + h + ' h' : ''); };
const boton = (href, t) => '<a href="' + href + '" style="display:inline-block;background:#3C1AE9;color:#FFFFFF;text-decoration:none;font-size:13px;font-weight:bold;padding:7px 14px;border-radius:6px">' + t + '</a>';

// KPIs del tablero
const kpi = (href, l, n, s, osc) => '<td width="25%" style="background:' + (osc ? '#01022E' : '#F5F6FB') + ';border-radius:8px;padding:12px 8px;vertical-align:top"><a href="' + href + '" style="text-decoration:none">' +
  '<div style="font-size:12px;font-weight:bold;color:' + (osc ? '#FFB98A' : '#4A4B6A') + '">' + l + '</div><div style="font-size:26px;font-weight:bold;color:' + (osc ? '#FFFFFF' : '#01022E') + ';margin:2px 0">' + n + '</div>' +
  '<div style="font-size:11px;color:' + (osc ? '#D9DAEC' : '#4A4B6A') + '">' + s + '</div></a></td>';
const kpis = '<table width="100%" cellspacing="6" cellpadding="0" style="border-collapse:separate"><tr>' +
  kpi(w({ v: 'lista', f: 'abiertos' }), 'Abiertos', kb.abiertos ?? 0, (kb.pct_abiertos ?? 0) + ' % de ' + (kb.total ?? 0)) +
  kpi(w({ v: 'lista', f: 'cerrados' }), 'Cerrados', kb.cerrados ?? 0, (kb.pct_cerrados ?? 0) + ' % de ' + (kb.total ?? 0)) +
  kpi(w({ v: 'lista', f: 'respondidos' }), 'SLA 1ª respuesta', (kb.sla_respuesta_pct ?? 0) + ' %', (kb.respondidos_a_tiempo ?? 0) + ' de ' + (kb.respondidos ?? 0) + ' respondidos a tiempo') +
  kpi(w({ v: 'lista', f: 'vencidos' }), 'Vencidos', (kb.vencidos ?? 0) + ' <span style="font-size:14px;color:#FFB98A">' + (kb.pct_vencidos ?? 0) + ' %¹</span>', (kb.vencidos_abiertos ?? 0) + ' abiertos ' + (kb.pct_venc_abiertos ?? 0) + ' %² · ' + (kb.vencidos_cerrados ?? 0) + ' cerrados ' + (kb.pct_venc_cerrados ?? 0) + ' %²', true) +
  '</tr></table>';

// Matriz severidad × estado de SLA
const COLS = [['ab_tiempo', '#9BD2F3', '#01022E'], ['ab_riesgo', '#EE792F', '#01022E'], ['ab_vencido', '#01022E', '#FFFFFF'], ['ce_sla', '#E3EFFA', '#01022E'], ['ce_fuera', '#01022E', '#FFFFFF']];
const LIM = { P1: '30 min', P2: '2 h', P3: '24 h', P4: '48 h' };
const celda = (s, [col, bg, fg]) => { const n = Number(s[col] || 0);
  return '<td align="center" style="padding:3px"><' + (n ? 'a href="' + w({ v: 'lista', f: col, sev: s.sev }) + '"' : 'div') + ' style="display:block;background:' + (n ? bg : '#F3F3F7') + ';color:' + (n ? fg : '#8A8BA3') + ';border-radius:8px;padding:9px 0;font-size:16px;font-weight:bold;text-decoration:none">' + n + '</' + (n ? 'a' : 'div') + '></td>'; };
const TOT = { ab_tiempo: ['#F3F2FE', '#01022E', '#3C1AE9'], ab_riesgo: ['#FDEBDD', '#01022E', '#9A3F0C'], ab_vencido: ['#01022E', '#FFFFFF', '#FFB98A'], ce_sla: ['#E3EFFA', '#01022E', '#1F5F8B'], ce_fuera: ['#01022E', '#FFFFFF', '#FFB98A'] };
const celdaTot = ([col]) => { const t = tot[col] || {}; const [bg, fg, pc] = TOT[col];
  return '<td align="center" style="padding:3px"><a href="' + w({ v: 'lista', f: col }) + '" style="display:block;background:' + bg + ';border-radius:8px;padding:8px 0;text-decoration:none">' +
    '<div style="font-size:20px;font-weight:bold;color:' + fg + '">' + (t.n ?? 0) + '</div><div style="font-size:12px;font-weight:bold;color:' + pc + '">' + (t.pct ?? 0) + ' %</div></a></td>'; };
const th = (t) => '<td align="center" style="font-size:11px;font-weight:bold;color:#4A4B6A;padding:4px 2px">' + t + '</td>';
const matriz = '<table width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;table-layout:fixed">' +
  '<tr><td width="14%"></td><td colspan="3" align="center" style="font-size:13px;font-weight:bold;color:#01022E;padding-bottom:6px;border-bottom:3px solid #3C1AE9">Abiertos · ' + (kb.abiertos ?? 0) + '</td>' +
  '<td colspan="2" align="center" style="font-size:13px;font-weight:bold;color:#01022E;padding-bottom:6px;border-bottom:3px solid #9BD2F3">Cerrados · ' + (kb.cerrados ?? 0) + '</td></tr>' +
  '<tr><td></td>' + th('En tiempo') + th('En riesgo') + th('Vencido') + th('En SLA') + th('Fuera de SLA') + '</tr>' +
  mx.map(s => '<tr><td style="padding:3px 0"><div style="font-size:15px;font-weight:bold;color:#01022E">' + esc(s.sev) + '</div><div style="font-size:10px;color:#4A4B6A">' + LIM[s.sev] + '</div></td>' + COLS.map(cc => celda(s, cc)).join('') + '</tr>').join('') +
  '<tr><td style="padding-top:8px;border-top:2px solid #01022E;font-size:14px;font-weight:bold;color:#01022E">Total</td>' + COLS.map(cc => celdaTot(cc).replace('<td align="center" style="padding:3px">', '<td align="center" style="padding:8px 3px 3px;border-top:2px solid #01022E">')).join('') + '</tr>' +
  '<tr><td></td><td colspan="3" align="center" style="font-size:11px;color:#4A4B6A;padding-top:4px">% sobre los ' + (kb.abiertos ?? 0) + ' abiertos</td><td colspan="2" align="center" style="font-size:11px;color:#4A4B6A;padding-top:4px">% sobre los ' + (kb.cerrados ?? 0) + ' cerrados</td></tr></table>';

// Abiertos por atender
const nV = pa.filter(x => x.estado === 'vencido').length;
const filasPA = pa.slice(0, 6).map(x => { const v = x.estado === 'vencido'; const m = Number(x.min);
  return '<tr><td style="padding:8px 0;border-top:1px solid #2E3070;width:92px"><span style="display:inline-block;background:' + (v ? '#FFB98A' : '#EE792F') + ';color:#01022E;font-size:10px;font-weight:bold;padding:3px 6px;border-radius:4px">' + (v ? 'VENCIDO' : 'EN RIESGO') + '</span></td>' +
    '<td style="padding:8px 4px;border-top:1px solid #2E3070;font-size:13px;color:#FFFFFF"><a href="' + w({ v: 'caso', c: x.caso }) + '" style="color:#FFFFFF;text-decoration:none"><b>#' + esc(x.caso) + ' ' + esc(x.sev) + '</b> · ' + esc(x.asunto) + ' · ' + esc(x.pendiente) + '</a></td>' +
    '<td align="right" style="padding:8px 0;border-top:1px solid #2E3070;font-size:13px;font-weight:bold;color:' + (v ? '#FFB98A' : '#FFFFFF') + ';white-space:nowrap">' + (m < 0 ? '+' + dur(m) : 'quedan ' + dur(m)) + '</td></tr>'; }).join('');
const porAtender = '<div style="background:#01022E;border-radius:10px;padding:14px 16px;margin-top:14px">' +
  '<div style="font-size:15px;font-weight:bold;color:#FFFFFF;margin-bottom:6px">Abiertos por atender · ' + pa.length + ' <span style="font-size:12px;font-weight:normal;color:#D9DAEC">' + nV + ' vencidos · ' + (pa.length - nV) + ' en riesgo</span></div>' +
  (pa.length ? '<table width="100%" cellspacing="0" cellpadding="0">' + filasPA + '</table>' + (pa.length > 6 ? '<div style="font-size:12px;color:#D9DAEC;padding-top:6px"><a href="' + w({ v: 'lista', f: 'abiertos' }) + '" style="color:#9BD2F3">…y ' + (pa.length - 6) + ' más en el tablero web</a></div>' : '') : '<div style="font-size:13px;color:#D9DAEC">Ningún abierto vencido ni en riesgo.</div>') + '</div>';

// Pendientes por responsable
const RESP = { lider: ['Tú (líder)', '#3C1AE9'], cliente: ['Cliente', '#EE792F'], ingenieria: ['Ingeniería', '#01022E'] };
const grupos = ['lider', 'cliente', 'ingenieria'].map(x => pe.find(g => g.responsable === x) || { responsable: x, n: 0, acciones: [] });
const totalAb = grupos.reduce((s, g) => s + Number(g.n || 0), 0);
const pendientes = '<div style="border:1px solid #E8EBF3;border-radius:10px;padding:14px 16px;margin-top:14px">' +
  '<div style="font-size:15px;font-weight:bold;color:#01022E">Pendientes de los ' + totalAb + ' abiertos <span style="font-size:12px;font-weight:normal;color:#4A4B6A">· quién tiene la siguiente acción</span></div>' +
  '<table width="100%" cellspacing="0" cellpadding="0" style="margin-top:8px"><tr>' + grupos.map(g => '<td width="33%" style="vertical-align:top;padding-right:8px"><a href="' + w({ v: 'lista', f: 'resp_' + g.responsable }) + '" style="text-decoration:none;color:#01022E">' +
    '<div style="border-top:4px solid ' + RESP[g.responsable][1] + ';padding-top:6px"><span style="font-size:13px;font-weight:bold">' + RESP[g.responsable][0] + '</span> <span style="font-size:20px;font-weight:bold;float:right">' + g.n + '</span></div>' +
    '<div style="font-size:12px;color:#2B2C4A;line-height:1.5;clear:both">' + (arr(g.acciones).length ? arr(g.acciones).map(a => a.n + ' ' + esc(String(a.pendiente).charAt(0).toLowerCase() + String(a.pendiente).slice(1))).join('<br>') : 'Nada pendiente') + '</div></a></td>').join('') + '</tr></table></div>';

const nota = '<div style="font-size:11px;color:#64748B;line-height:1.5;margin-top:10px">% de abiertos sobre los ' + (kb.abiertos ?? 0) + ' abiertos · % de cerrados sobre los ' + (kb.cerrados ?? 0) + ' cerrados · ¹ vencidos sobre los ' + (kb.total ?? 0) + ' casos · ² reparto sobre los ' + (kb.vencidos ?? 0) + ' vencidos. ' +
  'Vencido: pasó el límite de su severidad sin respuesta aprobada (P1 30 min · P2 2 h · P3 24 h · P4 48 h). En riesgo: más del 80 % del límite. SLA 1ª respuesta: respondidos dentro del límite sobre todos los respondidos, abiertos o cerrados.</div>';

const decis = (c.decisiones || []).map(d =>
  '<tr><td style="padding:10px 0;border-top:1px solid #E8EBF3"><div style="font-size:14px;color:#01022E;font-weight:bold">' + esc(d.etiqueta) + ' #' + d.numero_caso + ' · ' + esc(d.severidad) + ' ' + esc(d.pais) + '</div>' +
  '<div style="font-size:12px;color:#64748B">' + esc(d.cliente) + ' · ' + esc(d.plazo) + '</div></td>' +
  '<td align="right" style="padding:10px 0;border-top:1px solid #E8EBF3">' + boton(BOT + 'pen', 'Revisar') + '</td></tr>').join('');
const bloqueDec = decis ? '<table width="100%" cellspacing="0" cellpadding="0">' + decis + '</table>' : '<p style="color:#067647">Nada pendiente de tu decisión.</p>';
const destinos = ['pen', 'inc', 'sla', 'pat'];
const imgs = (gr.urls || []).map((u, i) =>
  '<div style="margin:0 0 18px"><a href="' + BOT + destinos[i] + '" style="text-decoration:none">' +
  '<img src="' + u.replace(/&/g, '&amp;') + '" alt="' + esc(gr.titulos[i]) + '" width="632" style="display:block;width:100%;max-width:632px;height:auto;border:1px solid #E8EBF3;border-radius:6px">' +
  '<div style="font-size:12px;color:#3C1AE9;margin-top:4px">' + esc(gr.titulos[i]) + ' · ver detalle en Telegram →</div></a></div>').join('');
const titulos = ['Estado:', 'SLA en riesgo:', 'Incidentes:', 'Patrones:', 'Calidad de la IA:', 'Prioridad de hoy:'];
let lectura = esc(c.p4 || '');
for (const t of titulos) lectura = lectura.split(t).join('<b>' + t + '</b>');
lectura = lectura.replace(/\n/g, '<br>');
const h2 = (t) => '<div style="font-size:16px;font-weight:bold;color:#3C1AE9;margin:22px 0 10px">' + t + '</div>';
const html =
  '<div style="background:#F5F6FB;padding:24px 12px;font-family:Arial,Helvetica,sans-serif">' +
  '<div style="max-width:680px;margin:0 auto;background:#FFFFFF;border:1px solid #E8EBF3;border-radius:10px;overflow:hidden">' +
  '<div style="background:#01022E;padding:20px 24px">' +
    '<div style="font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#9BD2F3">Soporte · Reporte del líder</div>' +
    '<div style="font-size:22px;font-weight:bold;color:#FFFFFF;margin-top:6px">' + fecha + ' · ' + hora + '</div></div>' +
  '<div style="background:' + S[1] + ';padding:14px 24px;border-bottom:1px solid #E8EBF3">' +
    '<span style="display:inline-block;background:' + S[0] + ';color:#FFFFFF;font-size:12px;font-weight:bold;padding:3px 10px;border-radius:10px">' + S[2] + '</span> ' +
    '<span style="font-size:15px;font-weight:bold;color:' + S[0] + '">' + esc(c.motivo) + '</span></div>' +
  '<div style="padding:0 18px">' + h2('Severidad × estado de SLA <span style="font-size:12px;font-weight:normal;color:#64748B">· ' + esc(periodo) + ' · toca un número para ver los casos</span>') +
    kpis + '<div style="margin-top:10px">' + matriz + '</div>' + porAtender + pendientes + nota +
    '<div style="text-align:center;margin-top:16px">' + boton(w({}), 'Abrir tablero web') + '</div></div>' +
  '<div style="padding:0 24px">' + h2('Necesita tu decisión') + bloqueDec +
    (c.prioridad ? '<div style="margin-top:14px;padding:12px 14px;background:#F2EEFF;border-radius:6px;font-size:14px;color:#01022E"><b>Prioridad de hoy:</b> ' + esc(c.prioridad) + '</div>' : '') +
    h2('Gráficas · toca una para ver el detalle') + imgs +
    h2('Lectura del día') + '<div style="font-size:14px;line-height:1.6;color:#01022E">' + lectura + '</div></div>' +
  '<div style="background:#F9FAFE;border-top:1px solid #E8EBF3;padding:14px 24px;margin-top:20px;font-size:12px;color:#64748B;line-height:1.5">' +
    'Tablero, cifras y pendientes calculados en SQL (v_tablero_b, v_reporte_lider); la IA solo redacta la lectura del día. Periodo de los cerrados: ' + esc(periodo) + '. Las cifras del tablero llevan al detalle en la web; los botones de decisión abren el bot de Telegram para aprobar. DEMO: datos sintéticos.' +
  '</div></div></div>';
const sem = { rojo: '🔴', amarillo: '🟡', verde: '🟢' }[c.semaforo] || '';
return [{ json: { para: dest.lider, asunto: sem + ' Soporte · ' + c.motivo + ' · ' + $now.setZone('America/Bogota').setLocale('es').toFormat('ccc d LLL'), html } }];

// Gráficas a partir de conteos agregados en SQL (v_graficas_diarias). No viaja texto de tickets ni datos personales.
// Paleta tomada del sitio público de Truora (sin logos). Chart.js v2 en QuickChart; la config va como JS para usar funciones.
// URLs completas: no vencen (las cortas gratuitas vencen a los 3 días). El periodo lo fija config_reporte.
const g = $('Leer datos de gráficas').first().json || {};
const arr = (v) => Array.isArray(v) ? v : (typeof v === 'string' ? JSON.parse(v || '[]') : []);
const obj = (v) => (v && typeof v === 'object') ? v : (typeof v === 'string' ? JSON.parse(v || '{}') : {});
const J = JSON.stringify;
const C = { morado: '#3C1AE9', naranja: '#EE792F', marino: '#01022E', celeste: '#9BD2F3', moradoClaro: '#A99BF5', naranjaClaro: '#F6B98F', gris: '#CBD5E1' };
const CLAROS = [C.celeste, C.moradoClaro, C.naranjaClaro, C.gris];
const GRID = '#E8EBF3', TICK = '#475569';
const url = (cfg) => 'https://quickchart.io/chart?w=900&h=500&bkg=white&f=png&c=' + encodeURIComponent(cfg);
const ge = obj(g.gestion_24h);
const P = ge.periodo || 'últimas 24 h';

const DL_SHOW = 'function(c){return c.dataset.data[c.dataIndex]>0}';
const DL_COLOR = 'function(c){var b=c.dataset.backgroundColor;b=Array.isArray(b)?b[c.dataIndex]:b;return ' + J(CLAROS) + '.indexOf(b)>=0?"' + C.marino + '":"#FFFFFF"}';
const titulo = (t) => 'title:{display:true,text:' + J(t) + ',fontSize:20,fontStyle:"bold",fontColor:"' + C.marino + '",padding:20}';
const leyenda = (pos) => 'legend:{position:"' + pos + '",labels:{fontColor:"#334155",fontSize:14,boxWidth:14,padding:18}}';
const eje = (stacked, grid) => '{stacked:' + stacked + ',gridLines:{display:' + grid + ',color:"' + GRID + '",zeroLineColor:"' + GRID + '",drawBorder:false},ticks:{beginAtZero:true,precision:0,fontColor:"' + TICK + '",fontSize:14,padding:6}}';
const etiquetasBarras = 'datalabels:{display:' + DL_SHOW + ',color:' + DL_COLOR + ',font:{weight:"bold",size:15}}';

// 0) Gestión de casos: base de conocimiento vs interna
const total = Number(ge.total || 0);
const pct = (n) => total ? Math.round(100 * n / total) : 0;
const cats = [
  ['kb_resuelto', 'KB · resuelto', C.morado],
  ['kb_por_aprobar', 'KB · por aprobar', C.moradoClaro],
  ['interno_ingenieria', 'Interno · Ingeniería', C.naranja],
  ['interno_datos', 'Interno · esperando datos', C.naranjaClaro],
  ['interno_manual', 'Interno · manual', C.marino]
].filter(([k]) => Number(ge[k] || 0) > 0);
const v0 = cats.length ? cats.map(c => Number(ge[c[0]])) : [1];
const c0 = '{type:"doughnut",data:{labels:' + J(cats.length ? cats.map(c => c[1] + ': ' + ge[c[0]] + ' (' + pct(ge[c[0]]) + '%)') : ['Sin casos']) +
  ',datasets:[{data:' + J(v0) + ',backgroundColor:' + J(cats.length ? cats.map(c => c[2]) : [C.gris]) + ',borderColor:"#FFFFFF",borderWidth:4}]},' +
  'options:{cutoutPercentage:58,layout:{padding:{left:10,right:10,top:0,bottom:10}},' +
  titulo('Gestión de casos · ' + P + ' · ' + (ge.pct_kb ?? 0) + '% con base de conocimiento') + ',' + leyenda('right') + ',' +
  'plugins:{datalabels:{display:' + DL_SHOW + ',color:' + DL_COLOR + ',font:{weight:"bold",size:16},textAlign:"center",' +
  'formatter:function(v,c){var t=c.dataset.data.reduce(function(a,b){return a+b},0);return [v,Math.round(100*v/t)+"%"]}},' +
  'doughnutlabel:{labels:[{text:"' + total + '",font:{size:40,weight:"bold"},color:"' + C.marino + '"},{text:"casos",font:{size:15},color:"#64748B"}]}}}}';

// 1) Origen de la falla x severidad
const nombres = { truora: 'Truora (plataforma)', fuente_externa_gobierno: 'Fuente gobierno', meta_whatsapp: 'Meta / WhatsApp', integracion_cliente: 'Integración cliente', usuario_final: 'Usuario final', no_aplica: 'No aplica', indeterminado: 'Indeterminado', sin_clasificar: 'Sin clasificar' };
const colSev = { P1: C.naranja, P2: C.morado, P3: C.celeste, P4: C.gris };
const os = arr(g.origen_severidad);
const tot = (x) => ['P1', 'P2', 'P3', 'P4'].reduce((s, k) => s + Number(x[k] || 0), 0);
const sev1 = ['P1', 'P2', 'P3', 'P4'].filter(s => os.some(x => Number(x[s] || 0) > 0));
const c1 = '{type:"horizontalBar",data:{labels:' + J(os.length ? os.map(x => (nombres[x.origen] || x.origen) + ' (' + tot(x) + ')') : ['Sin tickets']) +
  ',datasets:' + J(sev1.map(s => ({ label: s, backgroundColor: colSev[s], maxBarThickness: 56, data: os.map(x => Number(x[s] || 0)) }))) + '},' +
  'options:{' + titulo('Tickets por origen de la falla y severidad · ' + P) + ',' + leyenda('bottom') + ',layout:{padding:{right:20}},' +
  'scales:{xAxes:[' + eje(true, true) + '],yAxes:[' + eje(true, false) + ']},plugins:{' + etiquetasBarras + '}}}';

// 2) SLA por severidad
const sl = arr(g.sla_por_severidad);
const est = [['en_plazo', 'En plazo', C.morado], ['en_riesgo', 'En riesgo (>80%)', C.naranjaClaro], ['vencido', 'Vencido', C.naranja]];
const c2 = '{type:"bar",data:{labels:' + J(sl.length ? sl.map(x => x.severidad) : ['Sin tickets']) +
  ',datasets:' + J(est.map(([k, l, col]) => ({ label: l, backgroundColor: col, maxBarThickness: 90, data: sl.map(x => Number(x[k] || 0)) }))) + '},' +
  'options:{' + titulo('SLA por severidad · ' + P) + ',' + leyenda('bottom') + ',' +
  'scales:{xAxes:[' + eje(true, false) + '],yAxes:[' + eje(true, true) + ']},plugins:{' + etiquetasBarras + '}}}';

// 3) Tendencia 7 días
const td = arr(g.tendencia_7d);
const maxY = Math.max(1, ...td.map(x => Number(x.total || 0)));
const c3 = '{type:"line",data:{labels:' + J(td.map(x => x.dia)) + ',datasets:' + J([
  { label: 'Tickets', borderColor: C.morado, backgroundColor: 'rgba(60,26,233,0.10)', fill: true, borderWidth: 3, pointRadius: 5, pointBackgroundColor: C.morado, cubicInterpolationMode: 'monotone', data: td.map(x => Number(x.total || 0)) },
  { label: 'Escalados a Ingeniería', borderColor: C.naranja, backgroundColor: C.naranja, fill: false, borderWidth: 3, pointRadius: 5, pointBackgroundColor: C.naranja, cubicInterpolationMode: 'monotone', data: td.map(x => Number(x.escalados || 0)) }
]) + '},options:{' + titulo('Tickets por día · últimos 7 días') + ',' + leyenda('bottom') + ',' +
  'scales:{xAxes:[' + eje(false, false) + '],yAxes:[{gridLines:{color:"' + GRID + '",zeroLineColor:"' + GRID + '",drawBorder:false},ticks:{beginAtZero:true,precision:0,suggestedMax:' + Math.ceil(maxY * 1.25) + ',fontColor:"' + TICK + '",fontSize:14}}]},' +
  'plugins:{datalabels:{display:' + DL_SHOW + ',align:"top",anchor:"end",offset:4,color:function(c){return c.dataset.borderColor},font:{weight:"bold",size:15}}}}}';

const titulos = ['Gestión de casos: base de conocimiento vs interna (' + P + ')', 'Origen de la falla y severidad (' + P + ')', 'SLA por severidad (' + P + ')', 'Tendencia 7 días'];
return [{ json: { tickets_24h: g.tickets_24h ?? 0, periodo: P, gestion: ge, titulos, urls: [url(c0), url(c1), url(c2), url(c3)] } }];
